def describe(self) -> List[str]:
    """Numarali, okunur adim listesi (gunluk ve testler icin)."""
    return [f"{i}. {op}" + (tr(" [YIKICI]") if op.destructive else "")
            for i, op in enumerate(self._items, 1)]
